const first = $input.first()?.json ?? {};
if (typeof first.code === 'number' && first.code !== 0) {
  throw new Error(`Nmap/SSH termino con codigo ${first.code}: ${(first.stderr || '').trim() || 'sin detalle en stderr'}`);
}
const xml = first.stdout || '';
if (!xml.includes('<nmaprun')) {
  throw new Error('La salida de Nmap no es un XML valido (falta <nmaprun>). stderr: ' + ((first.stderr || '').trim() || '(vacio)'));
}
const decode = (s) => (s || '').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');
const attr = (tag, name) => { const m = (tag || '').match(new RegExp('\\s' + name + '="([^"]*)"')); return m ? decode(m[1]) : ''; };

const hostBlocks = xml.match(/<host(?:\s[^>]*)?>[\s\S]*?<\/host>/g) || [];
const hosts = hostBlocks.map((block) => {
  const addrTags = block.match(/<address\s[^>]*\/?>/g) || [];
  const ipv4 = addrTags.find((t) => attr(t, 'addrtype') === 'ipv4');
  const statusTag = (block.match(/<status\s[^>]*\/?>/) || [''])[0];
  const hostnameTag = (block.match(/<hostname\s[^>]*\/?>/) || [''])[0];
  const osTag = (block.match(/<osmatch\s[^>]*\/?>/) || [''])[0];
  const ports = (block.match(/<port\s[^>]*>[\s\S]*?<\/port>/g) || []).map((p) => {
    const head = p.match(/<port\s[^>]*>/)[0];
    const stateTag = (p.match(/<state\s[^>]*\/?>/) || [''])[0];
    const svcTag = (p.match(/<service\s[^>]*\/?>/) || [''])[0];
    return {
      port: attr(head, 'portid'), protocol: attr(head, 'protocol'), state: attr(stateTag, 'state'),
      service: attr(svcTag, 'name') || 'unknown',
      version: [attr(svcTag, 'product'), attr(svcTag, 'version')].filter(Boolean).join(' ')
    };
  });
  return {
    ip: ipv4 ? attr(ipv4, 'addr') : 'Unknown', hostname: attr(hostnameTag, 'name') || 'Unknown',
    state: attr(statusTag, 'state') || 'Unknown', os: attr(osTag, 'name') || 'Unknown', ports
  };
});
return hosts.map((h) => ({ json: h }));

const items = $input.all().map((i) => i.json);
const active = items.filter((h) => h && h.state === 'up' && /^\d{1,3}(\.\d{1,3}){3}$/.test(h.ip || ''));
if (!active.length) throw new Error('Nmap no encontro ningun host activo en la red escaneada.');
const ports = new Set();
active.forEach((h) => (h.ports || []).forEach((p) => { if (p.state === 'open' && p.protocol === 'tcp' && p.port) ports.add(Number(p.port)); }));
const portList = ports.size ? [...ports].sort((a, b) => a - b).join(',') : '22,80,443,5678,8080';
const tz = 'America/Argentina/Mendoza';
const now = new Date();
const formatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: tz,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
});
const parts = formatter.formatToParts(now).reduce((acc, p) => ({ ...acc, [p.type]: p.value }), {});
const scan_id = `scan_${parts.year}${parts.month}${parts.day}_${parts.hour}${parts.minute}${parts.second}`;
const hostsArg = active.map((h) => h.ip).join(',');
const portsArg = portList;
if (!/^[0-9.,]+$/.test(hostsArg) || !/^(T:)?[0-9,]+$/.test(portsArg)) throw new Error('Argumentos con formato invalido.');
return [{ json: { scan_id, hostsArg, portsArg, host_count: active.length, active_hosts: active.map((h) => h.ip) } }];

const inputJson = $input.first().json;

if (inputJson.code === 75) {
  throw new Error('Ya hay un escaneo en curso en el host (lock activo). Reintentá en unos minutos.');
}
if (typeof inputJson.code === 'number' && inputJson.code !== 0) {
  throw new Error(`OpenVAS/SSH termino con codigo ${inputJson.code}: ${(inputJson.stderr || '').trim() || 'sin detalle en stderr'}`);
}

const xmlData = inputJson.stdout || '';

// Detectar error GMP (status 4xx/5xx)
const respMatch = xmlData.match(/<get_reports_response[^>]*status="(\d+)"[^>]*status_text="([^"]*)"/);
if (respMatch && parseInt(respMatch[1], 10) >= 400) {
  throw new Error(`GMP devolvio error ${respMatch[1]}: ${respMatch[2]}`);
}

// Distinguir reporte invalido o truncado de 0 vulnerabilidades (exigir apertura y cierre </report>)
if (!xmlData || !xmlData.includes('<report') || !xmlData.includes('</report>')) {
  throw new Error(`Salida de OpenVAS no contiene un reporte XML valido o completo (falta <report> o </report>). Primeros 300 chars: ${xmlData.substring(0, 300)}`);
}

const scanDateMatch = xmlData.match(/<scan_start>([^<]+)<\/scan_start>/) || xmlData.match(/<creation_time>([^<]+)<\/creation_time>/);
const scanDate = scanDateMatch ? new Date(scanDateMatch[1]).toISOString() : new Date().toISOString();

const scan_id = $('Build Hosts Argument').first().json.scan_id || 'unknown';

const decodeXML = (str) => {
  if (!str) return '';
  return str
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'").replace(/&amp;/g, '&');
};

// Eliminar bloques internos <detection>...</detection> para evitar truncamiento por tags <result> anidados
const cleanXml = xmlData.replace(/<detection>[\s\S]*?<\/detection>/g, '');
const resultBlocks = cleanXml.match(/<result id="[^"]+">[\s\S]*?<\/result>/g) || [];

const vulnerabilities = resultBlocks.map(block => {
  const nameMatch = block.match(/<name>([^<]+)<\/name>/);
  const hostMatch = block.match(/<host(?:\s[^>]*)?>([^<]+)/);
  const portMatch = block.match(/<port>([^<]+)<\/port>/);
  const severityMatch = block.match(/<severity>([^<]+)<\/severity>/);
  const threatMatch = block.match(/<threat>([^<]+)<\/threat>/);
  const descMatch = block.match(/<description>([\s\S]*?)<\/description>/);
  const solMatch = block.match(/<solution[^>]*>([\s\S]*?)<\/solution>/);
  const cveMatches = [...block.matchAll(/<ref\s+[^>]*?(?:type="cve"[^>]*?id="([^"]+)"|id="([^"]+)"[^>]*?type="cve")[^>]*\/?>/g)].map(m => m[1] || m[2]);

  const rawPort = portMatch ? portMatch[1].trim() : null;
  const cleanPort = (rawPort && !/^general/i.test(rawPort)) ? rawPort : null;
  const rawSev = severityMatch ? parseFloat(severityMatch[1]) : 0.0;
  const severity = (!isNaN(rawSev) && rawSev >= 0) ? Math.min(Math.max(rawSev, 0.0), 10.0) : 0.0;

  return {
    name: nameMatch ? decodeXML(nameMatch[1].trim()) : 'Vulnerabilidad sin nombre',
    host: hostMatch ? hostMatch[1].trim() : 'Unknown',
    port: cleanPort,
    severity,
    threat: threatMatch ? threatMatch[1].trim() : (severity >= 7.0 ? 'High' : severity >= 4.0 ? 'Medium' : severity > 0 ? 'Low' : 'Log'),
    description: descMatch ? decodeXML(descMatch[1].trim()) : '',
    solution: solMatch ? decodeXML(solMatch[1].trim()) : '',
    cve: cveMatches.length > 0 ? cveMatches.join(', ') : null,
    scan_date: scanDate
  };
});

return [{
  json: {
    scan_id,
    scanDate,
    vulnerabilities,
    total_found: vulnerabilities.length
  }
}];

const data = $input.first().json;
const vulnerabilities = data.vulnerabilities || [];

if (vulnerabilities.length === 0) {
  return [];
}

return vulnerabilities.map(vuln => ({
  json: {
    scan_id: data.scan_id,
    scan_date: vuln.scan_date || data.scanDate,
    host: vuln.host,
    vulnerability_name: vuln.name,
    severity: vuln.severity,
    port: vuln.port,
    cve: vuln.cve,
    description: vuln.description,
    solution: vuln.solution
  }
}));

const data = $('Parse Results').first().json;
const vulns = data.vulnerabilities || [];
const buildData = $('Build Hosts Argument').first().json;
const allHosts = buildData.active_hosts || [];
const scan_id = data.scan_id || buildData.scan_id || 'desconocido';

const critical = vulns.filter(v => v.severity >= 9.0);
const high = vulns.filter(v => v.severity >= 7.0 && v.severity < 9.0);
const medium = vulns.filter(v => v.severity >= 4.0 && v.severity < 7.0);
const low = vulns.filter(v => v.severity < 4.0);

const pct = (n) => vulns.length ? ((n / vulns.length) * 100).toFixed(1) : '0.0';

const tzOpts = { timeZone: 'America/Argentina/Mendoza', hour12: false };
const scanDateStr = new Date(data.scanDate).toLocaleString('es-AR', tzOpts);

const renderVulns = (vulnArray, title, limit = 10) => {
  if (vulnArray.length === 0) return `*No se encontraron vulnerabilidades ${title.toLowerCase()}.*\n`;
  let section = '';
  const visible = vulnArray.slice(0, limit);
  section += visible.map((v, i) => `
### ${i+1}. ${v.name}

**Host**: ${v.host}${v.port ? ':' + v.port : ''}
**Severidad**: ${v.severity}/10.0
**CVE**: ${v.cve || 'N/A'}

**Descripcion**:
${v.description ? (v.description.length > 300 ? v.description.substring(0, 300) + '...' : v.description) : '*Sin descripcion.*'}

**Solucion Recomendada**:
${v.solution ? (v.solution.length > 300 ? v.solution.substring(0, 300) + '...' : v.solution) : '*Sin solucion especificada.*'}

---
`).join('\n');
  if (vulnArray.length > limit) {
    section += `*...y ${vulnArray.length - limit} vulnerabilidades ${title.toLowerCase()} adicionales.*\n`;
  }
  return section;
};

const hostSection = allHosts.map(host => {
  const hostVulns = vulns.filter(v => v.host === host);
  return `
### ${host}
- Total: ${hostVulns.length} | Criticas: ${hostVulns.filter(v => v.severity >= 9.0).length} | Altas: ${hostVulns.filter(v => v.severity >= 7.0 && v.severity < 9.0).length} | Medias: ${hostVulns.filter(v => v.severity >= 4.0 && v.severity < 7.0).length} | Bajas/Info: ${hostVulns.filter(v => v.severity < 4.0).length}`;
}).join('\n');

const noHallazgos = vulns.length === 0 ? '\n> **Escaneo completado sin hallazgos de vulnerabilidades.**\n' : '';

const report = `
# Informe de Escaneo de Vulnerabilidades

**ID de Escaneo**: ${scan_id}
**Fecha del Escaneo**: ${scanDateStr}
**Hosts Escaneados**: ${allHosts.length} (${allHosts.join(', ')})
**Total de Vulnerabilidades**: ${vulns.length}
${noHallazgos}
---

## Resumen Ejecutivo

| Severidad | Cantidad | Porcentaje |
|-----------|----------|------------|
| Critica (9.0-10.0) | ${critical.length} | ${pct(critical.length)}% |
| Alta (7.0-8.9) | ${high.length} | ${pct(high.length)}% |
| Media (4.0-6.9) | ${medium.length} | ${pct(medium.length)}% |
| Baja e Informativa (0.0-3.9) | ${low.length} | ${pct(low.length)}% |

---

## Vulnerabilidades Criticas
${renderVulns(critical, 'criticas', 10)}

## Vulnerabilidades Altas
${renderVulns(high, 'altas', 10)}

## Vulnerabilidades Medias
${renderVulns(medium, 'medias', 15)}

## Vulnerabilidades Bajas e Informativas
${renderVulns(low, 'bajas e informativas', 20)}

---

## Resumen por Host
${hostSection || '*Sin datos de hosts.*'}

---

## Recomendaciones Generales

1. Priorizar la remediacion de vulnerabilidades criticas y altas de forma inmediata.
2. Aplicar parches y actualizaciones de seguridad para todos los servicios con hallazgos medios o superiores.
3. Revisar banners expuestos, metodos HTTP innecesarios y configuraciones debiles para reducir la superficie de ataque.
4. Implementar politicas de actualizacion regular de software y firmware.
5. Realizar escaneos de seguimiento tras aplicar correcciones para verificar la remediacion.

---

*Informe generado automaticamente por el sistema de escaneo de vulnerabilidades TASTSERV*
`;

return [{
  json: {
    report,
    scanDate: data.scanDate,
    summary: {
      scan_id,
      total: vulns.length,
      critical: critical.length,
      high: high.length,
      medium: medium.length,
      low: low.length
    }
  }
}];
